INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'marina-heights-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Marina Heights in Amwaj Islands.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من مارينا هايتس في Amwaj Islands.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Licensed real estate brokerage and property management firm specializing in waterfront residential communities and Grade-A commercial leasing. Focusing on Full Building Property Management, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة وساطة وإدارة عقارية مرخصة متخصصة في المجتمعات السكنية البحرية وتأجير المكاتب التجارية. من خلال خدمة إدارة عقارية شاملة للمباني نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Licensed real estate brokerage and property management firm specializing in waterfront residential communities and Grade-A commercial leasing.</p><p>Focusing on <strong>Full Building Property Management</strong>, our Amwaj Islands specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شركة وساطة وإدارة عقارية مرخصة متخصصة في المجتمعات السكنية البحرية وتأجير المكاتب التجارية.</p><p>من خلال خدمة <strong>إدارة عقارية شاملة للمباني</strong>، يعمل فريقنا في Amwaj Islands على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Marina Heights', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | مارينا هايتس', 'Executive guide by Marina Heights covering Full Building Property Management benchmarks in Bahrain.', 'دليل تنفيذي من مارينا هايتس حول معايير إدارة عقارية شاملة للمباني في البحرين.', 'Sustainability', '{"real_estate","sustainability","Amwaj Islands","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', true, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
